import java.util.ArrayList;
import java.util.Collections;
import pyjvm315.runtime.PyRuntime;

/** Same algorithm in primitive Java, runtime Java, and generated bytecode. */
public final class Bench {
    private static volatile long sink;
    private static final Object stepFunction = PyRuntime.makeFunction(
        "Bench", "runtimeStep", "", "i", "", null, null, Collections.emptyMap());

    static long direct(String kernel, long n) {
        long total = 0;
        switch (kernel) {
            case "arithmetic":
                long i = 0;
                while (i < n) { total += i * 3 + 7; i++; }
                return total;
            case "range_loop":
                for (long j = 0; j < n; j++) total += j;
                return total;
            case "calls":
                for (long j = 0; j < n; j++) total += directStep(j);
                return total;
            case "collections":
                // Preserve growth/allocation; do not replace with a closed form.
                ArrayList<Long> values = new ArrayList<>();
                for (long j = 0; j < n; j++) values.add(j + 1);
                for (int j = 0; j < n; j++) total += values.get(j);
                return total;
            default: throw new IllegalArgumentException(kernel);
        }
    }
    static long directStep(long i) { return i * 3 + 7; }

    public static Object runtimeStep(Object i) {
        return PyRuntime.add(PyRuntime.mul(i, 3L), 7L);
    }

    static Object runtime(String kernel, Object n) {
        Object total = 0L;
        if (kernel.equals("arithmetic")) {
            Object i = 0L;
            while (PyRuntime.truth(PyRuntime.lt(i, n))) {
                total = PyRuntime.add(total, runtimeStep(i));
                i = PyRuntime.add(i, 1L);
            }
            return total;
        }
        Object iterator = PyRuntime.iter(PyRuntime.range1(n));
        Object values = kernel.equals("collections") ? PyRuntime.list0() : null;
        while (PyRuntime.iterHasNext(iterator)) {
            Object i = PyRuntime.iterNext(iterator);
            switch (kernel) {
                case "range_loop": total = PyRuntime.add(total, i); break;
                case "calls":
                    Object args = PyRuntime.list0();
                    PyRuntime.listAppend(args, i);
                    total = PyRuntime.add(total, PyRuntime.callFunction(
                        stepFunction, args, PyRuntime.dict0()));
                    break;
                case "collections":
                    PyRuntime.callMethod1(values, "append", PyRuntime.add(i, 1L));
                    break;
                default: throw new IllegalArgumentException(kernel);
            }
        }
        if (values != null) {
            iterator = PyRuntime.iter(PyRuntime.range1(n));
            while (PyRuntime.iterHasNext(iterator)) {
                Object i = PyRuntime.iterNext(iterator);
                total = PyRuntime.add(total, PyRuntime.getitem(values, i));
            }
        }
        return total;
    }

    static long generated(String kernel, Object n) {
        Object result;
        switch (kernel) {
            case "arithmetic": result = Kernels.arithmetic(n); break;
            case "range_loop": result = Kernels.range_loop(n); break;
            case "calls": result = Kernels.calls(n); break;
            case "collections": result = Kernels.collections(n); break;
            default: throw new IllegalArgumentException(kernel);
        }
        return ((Number) result).longValue();
    }

    static long invoke(String mode, String kernel, long n) {
        switch (mode) {
            case "java": return direct(kernel, n);
            case "runtime": return ((Number) runtime(kernel, n)).longValue();
            case "generated": return generated(kernel, n);
            default: throw new IllegalArgumentException(mode);
        }
    }

    static long batch(String mode, String kernel, int size, int repetitions, long expected) {
        long checksum = 0;
        long start = System.nanoTime();
        for (int r = 0; r < repetitions; r++) {
            // Vary input to prevent invariant-result hoisting; prove both sizes safe.
            long n = size + (r & 1);
            checksum += invoke(mode, kernel, n);
        }
        long elapsed = System.nanoTime() - start;
        sink = checksum; // Consume results outside the timed loop.
        if (checksum != expected) throw new AssertionError("checksum " + checksum + " != " + expected);
        return elapsed;
    }

    static long expected(String kernel, int size, int repetitions) {
        return (repetitions / 2L + repetitions % 2) * direct(kernel, size)
            + (repetitions / 2L) * direct(kernel, size + 1L);
    }

    public static void main(String[] args) {
        String mode = args[0], kernel = args[1];
        int size = Integer.parseInt(args[2]);
        long warmupNs = Long.parseLong(args[3]) * 1_000_000L;
        long targetNs = Long.parseLong(args[4]) * 1_000_000L;
        int samples = Integer.parseInt(args[5]);
        Kernels.main(new String[0]); // Initialize Python functions outside timing.
        for (int n : new int[]{0, 1, 7, size, size + 1}) {
            long want = direct(kernel, n);
            long got = invoke(mode, kernel, n);
            if (want != got) throw new AssertionError(kernel + ": " + got + " != " + want);
            System.out.println("CHECK " + n + " " + got);
        }
        int reps = 1;
        // Calibration and JIT warmup are excluded from measurements.
        long deadline = System.nanoTime() + warmupNs;
        do {
            long elapsed = batch(mode, kernel, size, reps, expected(kernel, size, reps));
            if (elapsed < targetNs / 2 && reps < 1_048_576) reps *= 2;
        } while (System.nanoTime() < deadline);
        long want = expected(kernel, size, reps);
        for (int s = 0; s < samples; s++) {
            long elapsed = batch(mode, kernel, size, reps, want);
            System.out.println("SAMPLE " + ((double) elapsed / reps) + " " + reps + " " + sink);
        }
    }
}
